compile.workshop:
variables {
    player:
        0: p
}

rule ("string replace keeps reevaluating replacements") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Player Variable(Event Player, p, String Replace(Custom String("text"), Custom String("x"), Array(1, 2)));
        Set Player Variable(Event Player, p, String Replace((Event Player).p, Custom String("x"), Custom String("y")));
        Set Player Variable(Event Player, p, String Replace(Custom String("text"), Custom String("x"), (Event Player).p));
        Set Player Variable(Event Player, p, String Replace(Custom String("text"), Custom String("x"), String Slice((Event Player).p, 0, 1)));
        Set Player Variable(Event Player, p, String Replace(Custom String("text"), Custom String("x"), Update Every Frame(Event Player)));
        Set Player Variable(Event Player, p, String Replace(Custom String("text"), Custom String("x"), Update Every Frame(Up)));
    }
}

